#!/bin/bash
# Uninstall script for Eclipse Modeling Tools
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Eclipse Modeling Tools..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Eclipse Modeling Tools if running..."
pkill -f "Eclipse Modeling Tools" 2>/dev/null || true

# Kill application with bundle ID epp.package.modeling if running
echo "Stopping application with bundle ID epp.package.modeling if running..."
killall -9 "epp.package.modeling" 2>/dev/null || true

# Remove /Applications/Eclipse.app
echo "Removing /Applications/Eclipse.app..."
if [ -d "/Applications/Eclipse.app" ]; then
    rm -rf "/Applications/Eclipse.app" 2>/dev/null || true
elif [ -f "/Applications/Eclipse.app" ]; then
    rm -f "/Applications/Eclipse.app" 2>/dev/null || true
fi

# Remove /Applications/{'target': 'Eclipse Modeling.app'}
echo "Removing /Applications/{'target': 'Eclipse Modeling.app'}..."
if [ -d "/Applications/{'target': 'Eclipse Modeling.app'}" ]; then
    rm -rf "/Applications/{'target': 'Eclipse Modeling.app'}" 2>/dev/null || true
elif [ -f "/Applications/{'target': 'Eclipse Modeling.app'}" ]; then
    rm -f "/Applications/{'target': 'Eclipse Modeling.app'}" 2>/dev/null || true
fi

# Remove $HOME/.eclipse
echo "Removing $HOME/.eclipse..."
if [ -d "$HOME/.eclipse" ]; then
    rm -rf "$HOME/.eclipse" 2>/dev/null || true
elif [ -f "$HOME/.eclipse" ]; then
    rm -f "$HOME/.eclipse" 2>/dev/null || true
fi

# Remove $HOME/eclipse-workspace
echo "Removing $HOME/eclipse-workspace..."
if [ -d "$HOME/eclipse-workspace" ]; then
    rm -rf "$HOME/eclipse-workspace" 2>/dev/null || true
elif [ -f "$HOME/eclipse-workspace" ]; then
    rm -f "$HOME/eclipse-workspace" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/epp.package.modeling.plist
echo "Removing $HOME/Library/Preferences/epp.package.modeling.plist..."
if [ -d "$HOME/Library/Preferences/epp.package.modeling.plist" ]; then
    rm -rf "$HOME/Library/Preferences/epp.package.modeling.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/epp.package.modeling.plist" ]; then
    rm -f "$HOME/Library/Preferences/epp.package.modeling.plist" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
